// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2003, "6-7", [{"author":"М. Кронгауз","question":"Заглавные буквы В, М, Р, Н, Т, К есть и в латинском, и в русском алфавите. Однако только три из них обозначают совпадающие согласные звуки. Это:","choices":["М, Т, К","В, М, Р","М, Р, К","Р, Н, К","Н, Т, К"],"key":"А","review":["Внешность букв и звуки","Русские В, Р и Н выглядят как латинские B, P и H, но обозначают другие согласные.","М, Т и К обозначают соответственно [м], [т] и [к] в обоих алфавитах."]},{"author":"М. Кронгауз","question":"Петя — футболист. В чём он никогда не играл в футбол?","choices":["в бутсах","в чешках","в кедах","в кроссовках,","в гетрах"],"key":"Б","review":["Обувь для разных занятий","Бутсы, кеды и кроссовки — обувь для спортивных игр. На ногах у футболистов также бывают гетры.","Чешки — обувь для гимнастики или танцев. В футбол в них обычно не играют."]},{"author":"Н. Валеева","question":"Кукушка кукуш…нку\nКупила капюш…н.\nНадел кукуш…нок капюш…н.\nКак в капюш…не он смеш…н!\nСколько букв ё пропущено в скороговорке?","choices":["одна","две","три","более трёх","в этой скороговорке нет ни одной буквы ё"],"key":"Д","review":["Буква после ш","В словах «кукушонку», «кукушонок» и «капюшон» после ш под ударением пишется о.","В кратком прилагательном «смешон» тоже о. Ни в одном из пропусков ё не нужна."]},{"author":"Е. Муравенко","question":"У Васи забарахлил компьютер: одну из русских букв он повсюду стал заменять вопросительным знаком. Вот во что превратились после этого несколько русских слов: ?ора, ?орт, сто?, ба?. Какую букву \"невзлюбил\" компьютер?","choices":["г","к","л","п","с"],"key":"Б","review":["Одна буква во всех пропусках","Подставь одну и ту же букву в четыре места. Для первой пары нужны слова, начинающиеся с одной буквы, для второй — оканчивающиеся на неё.","Буква к даёт «кора», «корт», «сток» и «бак». Все четыре слова существуют."]},{"author":"Л. Фёдорова","question":"По сообщениям газет, один японский рыбак выловил на удочку «чудо-юдо» — молодого осьминога с 28 щупальцами! А сколько их обычно бывает у этого обитателя морских глубин?","choices":["4","5","6","8","40"],"key":"Г","review":["Название с числом","Слово «осьминог» связано со старым «осемь» — восемь. Вторая часть напоминает о ногах.","У обычного осьминога восемь рук. На необычный экземпляр с 28 указывает само условие."]},{"author":"Н. Валеева","question":"Каждый из этих глаголов описывает какое-то перемещение. Но один из них по смыслу сильно отличается от других. Какой?","choices":["бежать","брести","мчаться","пятиться","шагать"],"key":"Г","review":["Направление движения","Бежать, брести, мчаться и шагать обозначают разные способы двигаться, обычно вперёд.","Пятиться значит двигаться назад. Здесь главное различие — направление, а не темп."]},{"author":"И. Иткин","question":"В каком из этих слов непроизносимый согласный — непроверяемый?","choices":["сердце","счастливый","лестница","поздно","ни в каком"],"key":"В","review":["Как проверить согласную","В «сердце» д слышно в «сердечный», в «счастливый» т — в «счастье», в «поздно» д — в «опоздать».","Для «лестницы» нет подходящего проверочного слова с ясным т. Её написание нужно запомнить."]},{"author":"П. Аркадьев","question":"Чем сходны эти пять слов, вы, конечно, видите. Но по составу одно из них не похоже на остальные. Найдите его.","choices":["дочка","почка","внучка","штучка","печка"],"key":"Б","review":["К в суффиксе и корне","Дочка, внучка, штучка и печка связаны с «дочь», «внук», «штука» и «печь». В них есть уменьшительный суффикс -к-.","«Почка» не образована от слова без к; согласная относится к корню почк-."]},{"author":"Е. Муравенко","question":"Какой термин не имеет отношения к изучению языка?","choices":["Ребус А","Ребус Б","Ребус В","Ребус Г","Ребус Д"],"key":"Г","review":["Пять терминов в ребусах","Первые ребусы и последний дают «приставка», «окончание», «слог» и «буква». Это термины о языке и письме.","В ребусе Г «ГИ по Т» даёт «гипот». От «пень» оставляем «ен», читаем У и берём «за» из «ваза». Получается «гипотенуза» — сторона прямоугольного треугольника."],"figure":{"options":[{"src":"assets/medvezhonok/2003/6-7-09-rebus-1.webp","description":"Буква П, число 300 и А внутри К.","pixelWidth":141,"pixelHeight":66},{"src":"assets/medvezhonok/2003/6-7-09-rebus-2.webp","description":"Дверь, буква И, сани и буква Е.","pixelWidth":172,"pixelHeight":66},{"src":"assets/medvezhonok/2003/6-7-09-rebus-3.webp","description":"Слон, запятая и буква Г.","pixelWidth":131,"pixelHeight":66},{"src":"assets/medvezhonok/2003/6-7-09-rebus-4.webp","description":"Маленькие ГИ на большой Т, пень с запятыми по краям, буква У и ваза с двумя запятыми слева.","pixelWidth":223,"pixelHeight":73},{"src":"assets/medvezhonok/2003/6-7-09-rebus-5.webp","description":"Бусы с двумя запятыми и К внутри А.","pixelWidth":118,"pixelHeight":72}]},"reviewedEdition":true},{"author":"И. Иткин","question":"У какого из следующих прилагательных в краткой форме единственного числа мужского рода появляется беглый гласный?","choices":["быстрый","добрый","пёстрый","хитрый","храбрый"],"key":"Г","review":["Гласный в краткой форме","Краткие формы мужского рода: «быстр», «добр», «пёстр», «хитёр», «храбр».","Только в «хитёр» между т и р появляется новый гласный, которого в «хитрый» нет."]},{"author":"К. Кноп","question":"У Лермонтова в «Тамбовской казначейше» читаем:\nНа кудри мягкие надета\nЕрмолка вишневого цвета\nС каймой и кистью золотой,\nДар молдаванки молодой.\nКакие слова употреблены здесь с отклонением от современной литературной нормы?","choices":["надета","вишневого","молдаванки","вишневого и молдаванки","надета, вишневого, молдаванки"],"key":"Б","review":["Старинное ударение","Ритм строки «Ермолка вишневого цвета» требует первого ударного слога в слове «ви́шневого».","В современной норме говорят «вишнёвого». «Надета» и «молдаванки» употреблены нормативно."]},{"author":"Е. Муравенко","question":"Сколько слов из списка можно понять и как существительное, и как глагол: брать, дать, жать, знать, мать, рать, рвать, стать?","choices":["одно","два","три","четыре","пять"],"key":"Б","review":["И глагол, и существительное","«Знать ответ» содержит глагол, «городская знать» — существительное со значением знатных людей.","«Стать врачом» содержит глагол, «лошадиная стать» — существительное со значением склада тела. Всего два слова."]},{"author":"Н. Валеева","question":"Сколько слов из списка содержат общий корень: высотный, полтораста, сотник, сотовый, стократный, сторожевой, трёхсотлетие?","choices":["два","три","четыре","пять","шесть"],"key":"В","review":["Общий корень со «сто»","Число сто узнаётся в «полтораста», «сотник», «стократный» и «трёхсотлетие», где корень меняет форму сто-/ста-/сот-.","«Высотный» связан с высотой, «сотовый» — с сотами, «сторожевой» — со сторожем. Подходят четыре слова."]},{"author":"И. Иткин","question":"Некоторые формы сравнительной степени прилагательных неплохо рифмуются между собой, например: смелее — веселее. Даны ещё некоторые пары форм сравнительной степени:\n1) теснее — честнее; 2) живее — красивее; 3) жарче — ярче; 4) жёстче — проще. \nВ какой из пар рифмы нет?","choices":["в первой","во второй","в третьей","в четвёртой","рифма есть во всех парах"],"key":"Б","review":["От ударного гласного","Рифму проверяют на слух от ударного гласного до конца слова. В «тесне́е — честне́е» совпадает «-не́е», в «жа́рче — я́рче» — «-а́рче». В «жёстче» сочетание стч звучит как щ, поэтому получается рифма к «про́ще».","В «живе́е» ударная е, а в «краси́вее» — и. Совпадения на письме недостаточно."]},{"author":"Е. Дмитриева","question":"В каком случае ниже представлены не варианты одного и того же слова, а разные слова?","choices":["невежа — невежда","галоша — калоша","ба́ржа — баржа́","строгать — стругать","берег — брег"],"key":"А","review":["Значение, а не произношение","«Невежа» — невоспитанный человек, «невежда» — человек, которому недостаёт знаний.","Один может быть невежей без невежества и наоборот. Остальные пары дают разные варианты одного слова."]},{"author":"И. Иткин","question":"Даны слова: 1) Вася; 2) ответственность; 3) чушь; 4) чепуха; 5) глупость. Какие из них могут выступать в качестве прямого дополнения при глаголе нести?","choices":["все, кроме 1","все, кроме 2","все, кроме 5","все, кроме 3 и 4","все"],"key":"В","review":["Прямое дополнение при «нести»","Можно нести Васю, ответственность, чушь или чепуху. Все эти слова отвечают на вопрос «нести кого или что?».","Говорят «нести глупости» во множественном числе. Сочетание «нести глупость» в этом значении обычно не употребляют."]},{"author":"Е. Муравенко","question":"Какое из словосочетаний не может употребляться как фразеологизм?","choices":["уткнуться носом","утереть нос","вытереть нос","совать нос не в своё дело","остаться с носом"],"key":"В","review":["Дословность и образность","«Утереть нос» может означать превзойти кого-то, «совать нос не в своё дело» — вмешиваться, «остаться с носом» — не получить желаемого.","«Уткнуться носом» тоже бывает образным, например о внимательном чтении. «Вытереть нос» в данном ряду означает буквальное действие."]},{"author":"Е. Муравенко","question":"Какое из данных пяти слов не обладает грамматическим свойством, которым обладают все остальные слова?","choices":["лыжи","санки","коньки","ролики","кроссовки"],"key":"Б","review":["Есть ли единственное число","От «лыжи», «коньки», «ролики» и «кроссовки» легко получить «лыжа», «конёк», «ролик», «кроссовка».","«Санки» употребляются только во множественном числе. Одни санки тоже называют этим словом."]},{"author":"Е. Дмитриева","question":"Какой тип склонения русских имен существительных не представлен в следующих примерах: книга, время, яблоня, кофе, тень, юноша, путь, пальто, мозоль?","choices":["1 склонение","2 склонение","3 склонение","разносклоняемые имена существительные","несклоняемые имена существительные"],"key":"Б","review":["Перечень склонений","«Книга», «яблоня» и «юноша» относятся к первому склонению. «Тень» и «мозоль» — к третьему. «Время» и «путь» разносклоняемые.","«Кофе» и «пальто» не склоняются. В списке нет существительных второго склонения."]},{"author":"Е. Дмитриева","question":"Редактор газеты отчего-то очень не любит слово пытаться. Подскажите репортёру, каким из пяти слов он может заменить в своей заметке это слово, чтобы смысл сказанного не изменился:","choices":["надеяться","изощряться","пробовать","усердствовать","надрываться"],"key":"В","review":["Сделать попытку","«Пытаться что-то сделать» — предпринимать попытку, даже если результат пока неизвестен.","«Пробовать что-то сделать» сохраняет тот же смысл. Например, «пытался открыть дверь» и «пробовал открыть дверь»."]},{"author":"И. Иткин","question":"Недавно в библиотеку Цветочного города поступило 76 495 новых книг. Со сколькими новыми книгами могут ознакомиться Незнайка и его друзья?","choices":["с семьдесят шесть тысяч четыреста девяносто пятью","с семьюдесятью шестью тысячами четырьмястами девяноста пятью","с семидесятью шестью тысячами четырьмястами девяноста пятью","с семидесяти шести тысяч четырехсот девяносто пятью","с семьюдесятью шестью тысячами четырестами девяностами пятью"],"key":"Б","review":["Склоняем всё числительное","В творительном падеже изменяются все части: «семьюдесятью шестью тысячами», «четырьмястами».","Дальше нужны «девяноста» и «пятью». Полная форма дана в варианте Б."]},{"author":"И. Рубанов","question":"В «Записках старого петербуржца» Льва Успенского упоминается магазин «Удивительно всё дёшево», где каждая вещь стоила ровно полтинник. «По правде сказать, не стоила она и четвертака», — писал Успенский. Во сколько же раз, по мнению писателя, хозяин магазина завышал цены?","choices":["менее чем в два","в два","более чем в два","по крайней мере, в три","более чем в четыре"],"key":"В","review":["Сравнение старых монет","Полтинник — 50 копеек, четвертак — 25. Полтинник вдвое больше четвертака.","Вещь, по словам автора, не стоила даже 25 копеек. Значит, цену завышали более чем вдвое."]},{"author":"И. Иткин","question":"Только одно из этих слов образовано от славянского слова око, имеющего значение ‘глаз’. Какое?","choices":["окно","околица","окинуть","океан","окулист"],"key":"А","review":["История «окна»","Окно исторически связано со славянским «око»: через него смотрят наружу, как через глаз.","«Окулист» связан с латинским oculus «глаз». Это родственное по истории слово, но оно не образовано от славянского «око»."]},{"author":"Н. Валеева","question":"Даны пары наречий-антонимов: (в)шутку — (в)серьёз; (на)яву — (во)сне; (в)слух — (про)себя; (в)доволь — (в)обрез; (в)начале — (на)последок; (не)спеша — (в)торопях; (на)перерез — (в)догонку. В скольких парах оба наречия пишутся слитно?","choices":["ни в одной","в одной","в двух","в трёх","более чем в трёх"],"key":"В","review":["Слитно в обеих частях","«Вначале — напоследок» и «наперерез — вдогонку» пишутся слитно в обоих случаях.","В других парах есть раздельное написание: «в шутку», «во сне», «про себя», «в обрез» или «не спеша». Подходят две пары."]},{"author":"Е. Дмитриева","question":"В известной старой песне есть такие строки:\nСреди долины <em>ровныя</em>\nНа гладкой высоте\nЦветёт, растёт высокий дуб\nВ могучей красоте (А.Ф.Мерзляков).\nСтаринной (церковнославянской по происхождению) формой какого падежа и числа является выделенное прилагательное?","choices":["им.п. мн. числа","род.п. ед. числа","род.п. мн. числа","вин.п. ед. числа","вин.п. мн. числа"],"key":"Б","review":["Падеж в старой песне","Предлог «среди» требует родительного падежа. Прилагательное согласуется с существительным «долины».","Современная форма — «среди долины ровной». «Ровныя» здесь родительный падеж единственного числа."]},{"author":"П. Аркадьев","question":"Если бы у глагола дерзить была форма первого лица единственного числа настоящего времени, то как бы она выглядела?","choices":["дерзаю","дерзну","дерзу","держу","дерзю"],"key":"Г","review":["Чередование согласных","В первом лице у ряда глаголов на -зить происходит з → ж: «возить — вожу», «грозить — грожу».","Тот же образец дал бы «держу» от «дерзить». В речи этой формы избегают, в том числе из-за совпадения с формой «держать»."]},{"author":"Е. Муравенко","question":"В какой паре слова имеют ровно два общих звука?","choices":["сбор — узор","водить — водный","блюдо — буду","отбой — борт","сёла — лось"],"key":"Г","review":["Сначала произнеси слова","«Отбой» произносится с [д] перед звонким [б]: [адбо́й]. В слове «борт» есть [б], [о], [р], [т].","Общие только [б] и [о]. Буква т в «отбой» не добавляет общего звука [т]."]},{"author":"П. Аркадьев","question":"Даны турецкие слова и словосочетания, а также их переводы на русский язык: ada — остров, adalar — острова, iki tas — две чашки, adam — человек, otuz adam — тридцать человек, taslar — чашки. Как будет по-турецки: тридцать островов, люди?","choices":["otuz adalar, adamlar","otuz ada, adam","otuz adalar, adam","otuz ada, adamlar","ikilar ada, adamlar"],"key":"Г","review":["Число и суффикс «-lar»","После числительного существительное употребляется в исходной форме: iki tas и otuz adam. Поэтому «тридцать островов» — otuz ada.","Без числительного множественное образуется с -lar: ada — adalar, tas — taslar. «Люди» — adamlar."],"reviewedEdition":true,"keyNote":"В исходном задании otuz ошибочно переведено как «двадцать». По-турецки otuz — «тридцать», а «двадцать» — yirmi. Перевод исправлен в условии. Правильный вариант по-прежнему Г."},{"author":"Н. Валеева","question":"Какое из перечисленных слов может быть понято как две разные формы соответствующего глагола?","choices":["вытрите","выберите","выполните","выпишите","выйдите"],"key":"В","review":["Написание и две формы","«Вы вы́полните задание завтра» говорит о будущем действии.","«Вы́полните задание сейчас!» — приказ. В обоих случаях пишется «выполните», а, например, «выпишете» и «выпишите» различаются на письме."]},{"author":"И. Иткин","question":"Даны прилагательные: внешний, тогдашний, нынешний, сегодняшний. Как раньше выглядело в русском языке слово там?","choices":["тама","таме","тами","тамо","у нас нет данных для ответа на этот вопрос"],"key":"Г","review":["Что сохранилось в слове","Прилагательные «тогдашний», «нынешний» и «сегодняшний» сохраняют гласную исходной формы, например «тогда».","«Тамошний» похоже сохраняет о. Старая форма наречия — «тамо»."]}], {"year":2003,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2003.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
